# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FELAK SURESİ VE SIĞINILAN KÖTÜLÜKLER (İSTİÂZE)</text>\n  <rect x="35" y="55" width="300" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Felak Suresi Okunuşu</text>\n  <text x="185" y="106" text-anchor="middle" font-size="11" fill="#334155">Bismillâhirrahmânirrahîm</text>\n  <text x="185" y="128" text-anchor="middle" font-size="11.5" fill="#1e293b">1. Kul eûzü birabbil felak.</text>\n  <text x="185" y="148" text-anchor="middle" font-size="11.5" fill="#1e293b">2. Min şerri mâ halak.</text>\n  <text x="185" y="168" text-anchor="middle" font-size="11.5" fill="#1e293b">3. Ve min şerri gâsikın izâ vekab.</text>\n  <text x="185" y="188" text-anchor="middle" font-size="11.5" fill="#1e293b">4. Ve min şerrin neffâsâti fil ukad.</text>\n  <text x="185" y="208" text-anchor="middle" font-size="11.5" fill="#1e293b">5. Ve min şerri hâsidin izâ hased.</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Allah\'a Sığınılan Dört Şer</text>\n  <text x="380" y="110" font-size="11.5" fill="#334155">• Yaratılmışların şerrinden (mâ halak)</text>\n  <text x="380" y="135" font-size="11.5" fill="#334155">• Karanlığı çöktüğü zaman gecenin şerrinden</text>\n  <text x="380" y="160" font-size="11.5" fill="#334155">• Düğümlere üfleyenlerin (fitnecilerin) şerrinden</text>\n  <text x="380" y="185" font-size="11.5" fill="#334155">• Kıskandığı vakit hasetçinin şerrinden</text>\n  <text x="512" y="215" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#16a34a">Sığınak: Sabahın Rabbi olan Yüce Allah!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE ÖZETİ: PEYGAMBERLERİN ÖZELLİKLERİ VE İLAHİ KİTAPLAR</text>\n  <rect x="35" y="55" width="305" height="180" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Peygamberlerin Sıfatları ve Görevleri</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Sıdk (Doğruluk) • Emanet (Güvenilirlik)</text>\n  <text x="55" y="130" font-size="11.5" fill="#334155">• Fetanet (Akıllı ve zeki olmak)</text>\n  <text x="55" y="152" font-size="11.5" fill="#334155">• İsmet (Günahtan korunmuş olmak)</text>\n  <text x="55" y="174" font-size="11.5" fill="#334155">• Tebliğ (Vahyi eksiksiz iletmek)</text>\n  <text x="55" y="202" font-size="11" font-weight="bold" fill="#854d0e">Beyan (Açıklama) • Temsil (Örnek olma) • Mucize</text>\n  <rect x="360" y="55" width="305" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Dört Büyük İlahi Kitap ve Suhuf</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Tevrat → Hz. Musa (a.s.)</text>\n  <text x="380" y="130" font-size="11.5" fill="#334155">• Zebur → Hz. Davud (a.s.)</text>\n  <text x="380" y="152" font-size="11.5" fill="#334155">• İncil → Hz. İsa (a.s.)</text>\n  <text x="380" y="174" font-size="11.5" fill="#334155">• Kur\'an-ı Kerim → Hz. Muhammed (s.a.v.)</text>\n  <text x="380" y="202" font-size="11" font-weight="bold" fill="#1e40af">100 Suhuf: Adem (10), Şit (50), İdris (30), İbrahim (10)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VAHYİN REHBERLİĞİ VE HAYATIMIZA YANSIMALARI</text>\n  <rect x="40" y="60" width="190" height="170" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="135" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. Tevhid İnancı</text>\n  <text x="135" y="118" text-anchor="middle" font-size="11.5" fill="#334155">Tüm peygamberler</text>\n  <text x="135" y="138" text-anchor="middle" font-size="11.5" fill="#334155">Allah\'ın birliğini ve</text>\n  <text x="135" y="158" text-anchor="middle" font-size="11.5" fill="#334155">O\'na kulluk edilmesini</text>\n  <text x="135" y="178" text-anchor="middle" font-size="11.5" fill="#334155">bildirmiştir.</text>\n  <rect x="255" y="60" width="190" height="170" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Güzel Ahlak</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#334155">Doğruluk, emanete</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11.5" fill="#334155">riayet, adalet ve</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11.5" fill="#334155">kıskançlıktan (haset)</text>\n  <text x="350" y="178" text-anchor="middle" font-size="11.5" fill="#334155">uzak durma öğütlenir.</text>\n  <rect x="470" y="60" width="190" height="170" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="565" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Tedbir ve Dua</text>\n  <text x="565" y="118" text-anchor="middle" font-size="11.5" fill="#334155">Kötülüklere karşı</text>\n  <text x="565" y="138" text-anchor="middle" font-size="11.5" fill="#334155">akıl ve iradeyle</text>\n  <text x="565" y="158" text-anchor="middle" font-size="11.5" fill="#334155">önlem alınır, ardından</text>\n  <text x="565" y="178" text-anchor="middle" font-size="11.5" fill="#334155">Allah\'a sığınılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
